query Estimate {
  accepted: estimatedCost(limit: 2)
  rejected: estimatedCost(limit: 16)
}

query TooDeep {
  posts(limit: 1) {
    related {
      related {
        title
      }
    }
  }
}

query TooBroad {
  posts(limit: 1) {
    a: title
    b: title
    c: title
    d: title
    e: title
  }
}
